int minEatingSpeed(const std::vector<int>& piles, long long h) {
    int lo = 1, hi = *std::max_element(piles.begin(), piles.end());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        long long hours = 0;
        for (int p : piles)
            hours += p / mid + (p % mid != 0);
        if (hours <= h) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

